 refs+=f'<li><a data-reference-source="1" href="{html.escape(s["url"],quote=True)}" target="_blank" rel="noopener">[{s["id"]}] {html.escape(s["titre"])}</a> — {html.escape(s["editeur"])} ; {html.escape(s["version_annee"])}. {html.escape(s["section_page"])}. Limites : {html.escape(s["limites"])}</li>'
