# Sciences : six disciplines locales, sémiologie ouverte en premier.
def chain(labels,caption):
 out='<figure><svg role="img" aria-label="'+html.escape(caption,quote=True)+'" viewBox="0 0 450 '+str(len(labels)*78)+'" style="display:block;width:100%;height:auto;max-width:600px;margin:auto">'
 for i,txt in enumerate(labels):
  y=i*78+5;out+=f'<rect x="8" y="{y}" width="434" height="52" rx="8" fill="#eff5f7" stroke="#28546d"/><text x="225" y="{y+32}" fill="#183a55" font-size="17" text-anchor="middle">{html.escape(txt)}</text>'
  if i<len(labels)-1:out+=f'<text x="225" y="{y+74}" fill="#183a55" font-size="22" text-anchor="middle">↓</text>'
 return out+'</svg><figcaption>'+caption+'</figcaption></figure>'
def links(a,b,c,end):return ''.join('<div class="key"><b>'+label+'</b> '+v+'</div>' for label,v in zip(['Science → clinique.','Science → examen.','Science → traitement.','À retenir.'],[a,b,c,end]))
A=R/'assets/img/e14/alpha/codex';A.mkdir(parents=True,exist_ok=True);shutil.copy2(C/'pancreas-openstax2013.jpg',A/'pancreas-openstax2013.jpg');(D/'figures').mkdir(exist_ok=True);shutil.copy2(C/'pancreas-openstax2013.jpg',D/'figures/pancreas-openstax2013.jpg');shutil.copy2(C/'figure.json',D/'figure-license-metadata.json')
def pancreas(which):
 return f'''<figure id="e14-figure-{which}" style="max-width:56rem;margin:1.4em auto"><div style="position:relative;background:white"><img src="assets/img/e14/alpha/codex/pancreas-openstax2013.jpg" alt="Original OpenStax 2013 : pancréas exocrine et îlots endocrines, avec une micrographie humaine normale et quatre repères français décrits sous l’image." style="display:block;width:100%;height:auto" width="1092" height="551">'''+''.join(f'<span class="e14-pin" style="position:absolute;left:{x}%;top:{y}%;border:2px solid #19364c;background:#fff2a8;color:#19364c;border-radius:50%;font:bold 14px/1.5 sans-serif;min-width:1.6em;text-align:center;transform:translate(-50%,-50%)">{n}</span>' for n,x,y in [(1,45,37),(2,44,48),(3,75,75),(4,83,88)])+'''</div><figcaption>Original humain publié par OpenStax College, Connexions 2013 ; micrographie University of Michigan Medical School ©2012. <a href="https://commons.wikimedia.org/wiki/File:1820_The_Pancreas.jpg" target="_blank" rel="noopener">Source de l’original</a> · <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a>. Pixels inchangés ; seuls quatre repères HTML sont ajoutés. 1 : tissu pancréatique ; 2 : région canalaire exocrine ; 3 : îlot dans la micrographie ; 4 : tissu acinaire adjacent. Les repères situent des régions, sans prouver le type du diabète. Les mentions anglaises appartiennent à l’original.</figcaption></figure>'''
sem=[]
def ss(mark,title,body):return f'<section class="ilot" id="e14-semio-{mark}" data-semiology="{mark}"><h3>{title}</h3>{body}</section>'
sem.append(ss('normal','Normalité : équilibre entre production et utilisation',f'''<p>Le pancréas endocrine adapte l’insuline aux besoins. La production hépatique de glucose et son utilisation tissulaire doivent rester coordonnées. La sécrétion de peptide C suit celle de l’insuline, mais leurs concentrations périphériques diffèrent. Un intervalle de laboratoire, un seuil de diabète et une cible de traitement ne désignent pas la même chose [S10, S21].</p><p>Pour la glycémie, le contexte comprend le jeûne, le plasma ou le sang capillaire, une charge orale et la grossesse. Un chiffre sous le seuil diagnostique ne constitue pas à lui seul un certificat de normalité universelle. Les références de l’analyseur et les conditions du prélèvement restent nécessaires [S4, S14].</p>'''))
sem.append(ss('signs','Signes : décrire avant d’interpréter','''<p>La polyurie correspond à un volume urinaire augmenté ; la pollakiurie à des mictions plus fréquentes. La soif, la nycturie, la perte de poids et la vision trouble sont précisées dans leur durée et circonstances. Vomissements, douleur abdominale, respiration profonde et troubles cognitifs changent le degré d’urgence. L’absence de plainte ne réfute pas un diabète chronique [S4, S11].</p><p>Le médecin distingue également les symptômes d’hypoglycémie survenant sous traitement de ceux de l’hyperglycémie. Une difficulté cognitive nécessitant de l’aide définit la gravité pratique de l’épisode hypoglycémique, sans exiger un chiffre unique [S8, S18].</p>'''))
sem.append(ss('mechanisms','Mécanismes : du glucose au signe','''<p>Une action insulinique insuffisante augmente la disponibilité du glucose au-delà de son utilisation. La perte urinaire de glucose entraîne de l’eau : la diurèse osmotique explique polyurie, soif et déplétion. La carence insulinique et la contre-régulation favorisent la production de cétones. L’acidose provoque une compensation respiratoire profonde [S11].</p><p>L’hyperosmolarité modifie les échanges d’eau et peut altérer la cognition ; elle peut préserver transitoirement la pression malgré un déficit d’eau. Le potassium plasmatique est un compartiment mesuré, pas le stock total. Sa redistribution explique une kaliémie initiale trompeuse puis sa chute sous insuline [S11, S17, S23].</p>'''))
sem.append(ss('examination','Examen : conditions, technique et limites',f'''<p>Le médecin examine conscience, respiration, pouls, pression, muqueuses et diurèse. Il recherche infection et ischémie. L’électrocardiogramme contribue à la sécurité électrolytique. Le pied est entièrement inspecté, les pouls sont palpés et la sensibilité protectrice est testée ; un résultat vasculaire rassurant ne clôt pas l’enquête si le contexte reste suspect [S11, S12, S13, S25].</p><p>Le {w('peptide','dosage du peptide C')} demande une glycémie simultanée et des conditions connues. Le rein élimine une partie du peptide C ; une insuffisance rénale peut le faire paraître conservé. La méthode et la durée du diabète modifient la conclusion [S10].</p>'''))
sem.append(ss('interpretation','Interprétation : trois questions indépendantes','''<p>La glycémie et l’HbA1c répondent à « le diabète est-il confirmé ? ». Cétones, pH, bicarbonate et osmolalité répondent à « existe-t-il une crise ? ». Les anticorps et la réserve insulinique contribuent à « de quel type s’agit-il ? ». Ces trois réponses ne sont pas interchangeables [S4, S10, S11].</p><p>Un anticorps isolé ne signifie pas automatiquement besoin immédiat d’insuline dans toute auto-immunité lente. Inversement, une sécrétion très basse peut imposer une couverture insulinique sans anticorps détecté. Le contexte clinique reste déterminant [S4, S5, S10].</p>'''))
sem.append(ss('differentials','Différentiels : choisir un discriminant','''<p>Une polyurie sans hyperglycémie demande une autre explication de la perte d’eau ; une simple fréquence mictionnelle n’a pas le même mécanisme. Devant une acidose avec cétones, le médecin recherche aussi jeûne, alcool et grossesse. Une acidose lactique, notamment sous metformine avec hypoxie ou insuffisance rénale aiguë, peut coexister ou dominer [S11, S19].</p><p>Dans le diabète confirmé, type 1, type 2, forme pancréatique, médicamenteuse et génétique sont discriminés par chronologie, phénotype, autoanticorps, sécrétion et explorations ciblées. Une liste d’hypothèses ne remplace pas cette comparaison [S4, S5, S10].</p>'''))
sem.append(ss('urgency','Urgence : le tableau prime sur l’étiquette','''<p>Altération de conscience, choc, respiration anormale, vomissements persistants et cétones élevées imposent une évaluation immédiate. L’acidocétose euglycémique est possible ; une glycémie modérée ne justifie pas l’attente. Une hypokaliémie augmente le danger de l’insuline précoce [S11].</p><p>Un pied infecté avec manifestations systémiques, une ischémie sévère, une gangrène ou un Charcot aigu impose le parcours spécialisé. Une neuropathie peut masquer la douleur. Le risque d’amputation ne se juge pas sur l’intensité de cette douleur [S13, S25].</p>'''))
sem.append(ss('limits','Limites : population et produit exact','''<p>Le consensus de crise est adulte ; il ne fournit pas une ordonnance pédiatrique. Grossesse, fragilité, insuffisance cardiaque et dialyse modifient surveillance et traitement. Les seuils d’HbA1c, peptide C et indices vasculaires gardent leurs limites de méthode et de population [S10, S11, S14, S25].</p><p>Les FI suisses de plusieurs concentrés de potassium mentionnent acidose et déshydratation grave comme contre-indications. Les produits cristalloïdes ont aussi leurs propres limites. Une recommandation syndromique n’efface pas cette divergence : le choix opérationnel relève d’un protocole hospitalier expert et d’une vérification pharmaceutique, sans délai évitable devant le risque vital [S24, S26, S27, S29, S30, S31].</p>'''))
sem.append(ss('sources','Sources : quelle preuve pour quelle observation ?','''<p>L’OMS 2019 [S4] étaye la définition et le typage clinique ; la SSED 2023 [S5] situe l’insulinodéficience et les cibles. Jones et Hattersley [S10] étayent les limites du peptide C ; le consensus EASD/JBDS conjoint 2024 [S11] et JBDS [S17] étayent crises et temporalité. Les critères suisses de suivi [S12], QCARE [S13] et IWGDF/ESVS/SVS [S25] fondent l’examen du pied et ses limites.</p><p>Les FI [S18, S19, S23, S24, S26–S31] concernent leurs produits exacts. La source anatomique [S21] explique le pancréas normal ; la figure historique a sa preuve de licence distincte. Aucun test technique ni cette auto-relecture n’équivaut à un examen médical humain.</p>'''))
sem_head='<section class="ilot" id="e14-s-semio-cours"><h2>Pour la leçon : quelle est la sémiologie fondamentale et analytique ?</h2><p>La sémiologie relie une plainte à un mécanisme, puis à un examen capable de modifier la décision. La glycémie est une mesure ; sa signification dépend de la situation et de l’état du patient [S4, S11].</p>'+chain(['Plainte et chronologie documentées','Mécanisme et risque immédiat recherchés','Examen ciblé et conditions précisées','Décision, explication et suivi écrits'],'Démarche logique non anatomique, sans score : contexte → hypothèse → examen → action [S4, S10, S11].')+'</section>'
sem_end=links('Une polyurie et une respiration profonde ne décrivent pas le même mécanisme.','Glycémie, cétones et peptide C répondent à des questions distinctes.','La gravité et le besoin d’insuline sont traités avant le classement définitif.','Une interprétation explicite conserve contexte, limites et action attendue.')
units={'semio':sem_head+''.join(sem)+sem_end}
units['anat']=f'''<section class="ilot" id="e14-s-anat-cours"><h2>Anatomie : un même organe, deux fonctions</h2><p>Le pancréas est un organe allongé situé en grande partie en arrière de la partie inférieure de l’estomac. Il participe à la digestion par son tissu exocrine et à la régulation des nutriments par ses îlots endocrines. Cette organisation évite de confondre maladie du pancréas et mécanisme exclusivement auto-immun [S21].</p><p>Les acini sécrètent des enzymes digestives drainées vers l’intestin par le système canalaire. Les îlots sont des groupes cellulaires distincts qui sécrètent notamment insuline et glucagon vers la circulation. La figure originale situe ces régions ; elle ne représente pas un pancréas diabétique [S21].</p>{pancreas('anatomie')}<p>Le repère 1 situe le tissu pancréatique au contact du duodénum. Le repère 2 suit une région des canaux exocrines. Le repère 3 identifie un îlot sur la micrographie ; le repère 4 montre le tissu exocrine voisin. Ces structures coexistent dans le même organe mais ne remplissent pas la même fonction [S21].</p><p>Une chirurgie, une inflammation ou une autre affection du pancréas exocrine peut s’accompagner d’une hyperglycémie ; l’histoire clinique oriente alors vers un diabète spécifique. Une insuline nécessaire ne transforme pas cette étiologie en diabète de type 1. L’anatomie donne une hypothèse, que les documents de chirurgie, le contexte et les examens ciblés doivent établir [S4, S20].</p><p>Inversement, une image morphologique normale ne mesure pas la réserve fonctionnelle des cellules β. La sécrétion endogène est explorée par un dosage interprété, et l’auto-immunité par des anticorps selon la question. Une exploration anatomique sans indication n’est pas un substitut au typage biologique [S4, S10].</p>{links('Une histoire de pancréatite ou de chirurgie change la recherche étiologique.','Le dossier pancréatique et les explorations orientées complètent les dosages ; une image normale ne mesure pas l’insuline.','Le besoin d’insuline se traite selon le déficit fonctionnel, même si la cause est pancréatique.','La figure explique une architecture normale, sans établir la cause d’un diabète.')}{src('[S21] §17.9, anatomie normale ; [S4] tableau 1 et typage ; [S10] sécrétion ; [S20] distinction type/traitement.')}</section>'''
units['histo']=f'''<section class="ilot" id="e14-s-histo-cours"><h2>Histologie : distinguer tissu observé et fonction mesurée</h2><p>La micrographie normale montre l’association d’un îlot endocrine et du tissu acinaire exocrine. Les cellules β produisent l’insuline ; les cellules α produisent le glucagon. D’autres cellules endocrines sécrètent notamment somatostatine et polypeptide pancréatique. Une coupe normale ne démontre pas le type de diabète d’un patient [S21].</p>{pancreas('histologie')}<p>Le repère 3 se trouve dans la zone d’îlot et le repère 4 dans le tissu acinaire adjacent. Les annotations anglaises sur les cellules appartiennent à l’illustration d’origine. La simple teinte de cette image ne devient pas un test diagnostique de l’auto-immunité, de la masse β ou d’une carence en insuline. Cette réserve évite d’attribuer à une image pédagogique une performance clinique qu’elle ne possède pas [S21, S4].</p><p>Le type 1 se caractérise par une destruction β-cellulaire souvent immunitaire. Le type 2 combine des degrés variables de dysfonction sécrétoire et de résistance à l’insuline. La clinique ne déduit pas ces mécanismes d’une biopsie pancréatique de routine : la classification pratique utilise le tableau clinique, l’évolution et les marqueurs disponibles [S4].</p><p>La production d’une molécule d’insuline s’accompagne de celle d’une molécule de peptide C lors du clivage de la proinsuline. Ce lien biochimique permet d’explorer la fonction du tissu sans compter ses cellules sur une coupe. La concentration périphérique dépend ensuite de l’élimination et de la glycémie ; elle n’est pas une mesure directe de la masse d’îlots [S10].</p><p>Une réserve mesurable au début peut persister malgré une auto-immunité ; une insuffisance rénale peut aussi majorer le résultat sanguin. Le médecin confronte donc structure théorique, marqueur de fonction et évolution avant de conclure. L’absence de critère histologique disponible ne doit pas retarder une insulinothérapie nécessaire [S4, S10, S5].</p>{links('La destruction et la dysfonction peuvent conduire au même symptôme d’hyperglycémie.','Le peptide C explore une sécrétion contextualisée ; les anticorps explorent un mécanisme immunitaire.','L’insulinodéficience clinique se traite sans attendre une preuve tissulaire.','Une image normale ne démontre ni auto-immunité, ni absence de maladie.')}{src('[S21] îlots/acini ; [S4] classification et limites ; [S10] fonction et clairance ; [S5] priorité à l’insulinodéficience.')}</section>'''
units['physio']=f'''<section class="ilot" id="e14-s-physio-cours"><h2>Physiologie : sécrétion, action et contre-régulation</h2><p>La régulation glycémique repose sur une sécrétion d’insuline adaptée et une réponse tissulaire suffisante. L’insuline facilite l’utilisation du glucose et son stockage, tout en freinant la production hépatique et la cétogenèse. Le glucagon augmente la disponibilité hépatique du glucose lorsque les besoins l’exigent. L’équilibre dépend donc de plusieurs flux, et pas de la seule quantité d’hormone mesurée [S21, S11].</p><p>L’insulinorésistance augmente les besoins. Une concentration d’insuline ou de peptide C située dans l’intervalle du laboratoire peut rester insuffisante pour ces besoins. À l’inverse, une faible sécrétion peut devenir cliniquement décisive même en l’absence d’obésité. Le phénotype n’est pas un dosage et le dosage n’est pas un type [S5, S10].</p>{chain(['Insuline adaptée aux besoins','Production hépatique freinée','Utilisation et stockage suffisants','Équilibre glycémique préservé'],'Schéma fonctionnel non anatomique du rôle de l’insuline ; les étapes décrivent une régulation, sans proportion quantitative [S21, S11].')}<p>Lorsque l’action insulinique devient insuffisante, le glucagon et les autres hormones de contre-régulation favorisent la production de glucose et de cétones. L’hyperglycémie provoque une diurèse osmotique et une déplétion hydrique. La réhydratation améliore à elle seule la perfusion rénale et peut faire baisser le glucose ; le débit d’insuline ne s’ajuste donc pas sans suivre cette évolution [S11, S17].</p><p>Une sécrétion résiduelle peut limiter la cétose sans prévenir l’hyperosmolarité. Cette dissociation explique qu’une personne âgée profondément déshydratée ait peu de cétones. Une forme mixte reste possible. La différence est fonctionnelle ; elle ne permet pas de classer automatiquement le diabète comme type 1 ou type 2 [S11].</p><p>Le peptide C renseigne sur la production endogène actuelle ; les autoanticorps peuvent renseigner sur le risque d’évolution de cette production. Un prélèvement pendant une hypoglycémie supprime physiologiquement la sécrétion et peut tromper. Une glycémie simultanée et une condition alimentaire connue sont donc indispensables [S10].</p>{links('Polyurie, soif et amaigrissement traduisent un déséquilibre des flux et des pertes.','Le peptide C répond à une question de sécrétion, pas à la confirmation du diabète.','Le déficit absolu impose une couverture insulinique ; l’état hyperosmolaire demande aussi une correction hydrique prudente.','La même hyperglycémie peut résulter de mécanismes différents et exige un contexte.')}{src('[S10] physiologie et prélèvement ; [S5] résistance/déficit ; [S11] pathogénie et traitement ; [S17] temporalité.')}</section>'''
units['bioch']=f'''<section class="ilot" id="e14-s-bioch-cours"><h2>Biochimie : cétones, osmoles et potassium</h2><p>La carence en insuline et la contre-régulation favorisent la lipolyse et la production hépatique de cétones. Le β-hydroxybutyrate est le principal cétoacide mesuré dans l’acidocétose. La réaction urinaire au nitroprussiate mesure surtout l’acétoacétate ; elle ne mesure pas le β-hydroxybutyrate. La cétonurie peut donc sous-estimer le début et surestimer la persistance lorsque le β-hydroxybutyrate se convertit en acétoacétate pendant l’amélioration [S11].</p><p>L’accumulation d’acides s’accompagne d’une baisse du bicarbonate et du pH. Le {w('anion','trou anionique')} estime les charges non mesurées à partir du sodium, du chlorure et du bicarbonate. Il peut rester trompeur après remplissage chloré : une acidose hyperchlorémique n’est pas nécessairement une cétose persistante. La résolution se fonde sur les cétones et le pH ou le bicarbonate [S11].</p>{chain(['Déficit insulinique et pertes urinaires','Potassium total diminué','Kaliémie initiale parfois normale','Insuline : potassium vers les cellules'],'Chaîne non anatomique des risques potassiques ; la normalité apparente du plasma ne mesure pas le stock corporel [S11, S23].')}<p>Le sodium et le glucose contribuent à la tonicité. L’{w('osmoles','osmolalité efficace et totale')} est calculée avec la formule et les unités indiquées. La formule efficace exclut l’urée ; la formule totale l’inclut. Une valeur efficace &gt;300 ou totale &gt;320 mOsm/kg intervient dans les critères hyperosmolaires 2024, mais jamais seule [S11, figure 2].</p><p>Pendant la correction, une baisse du glucose déplace l’eau et peut augmenter la natrémie. Cette hausse initiale ne constitue pas, seule, une indication de soluté hypotonique. L’équipe suit la trajectoire de l’osmolalité, la diurèse, la circulation et le sodium, en évitant une correction trop rapide [S11, S17].</p><p>L’insuline fait rentrer le potassium dans les cellules. Les concentrés de potassium ont des concentrations différentes et ne sont jamais injectés non dilués. Les contre-indications exactes des produits suisses empêchent de transformer mécaniquement la formule syndromique en ordonnance d’ampoules [S23, S24, S26, S29].</p>{links('Respiration profonde et troubles cognitifs peuvent traduire acidose et hypertonicité.','Le dosage sanguin des cétones est préférable à la seule bandelette pour suivre l’acidocétose.','L’équipe coordonne eau, insuline, glucose et électrolytes selon un protocole surveillé.','La formule et le compartiment mesuré changent le sens d’un chiffre.')}{src('[S11] §3–4 et figure 2 ; [S17] osmolalité ; [S23–S24, S26, S29] manipulation et précautions.')}</section>'''
units['gene']=f'''<section class="ilot" id="e14-s-gene-cours"><h2>Génétique et immunologie : préciser sans retarder les soins</h2><p>La classification de l’OMS distingue défauts monogéniques de la cellule β, anomalies monogéniques de l’action de l’insuline et autres syndromes génétiques. Avant six mois, une cause monogénique est prioritaire. Chez un sujet jeune, l’histoire familiale et le profil clinique peuvent justifier une consultation spécialisée. Les fréquences dépendent de la population ; un âge n’est pas à lui seul un test génétique [S4].</p><p>La recherche d’auto-immunité utilise notamment les anticorps contre la décarboxylase de l’acide glutamique, l’antigène des îlots 2, le transporteur du zinc 8 et l’insuline. Le médecin tient compte de la durée et d’une insulinothérapie déjà reçue. Une négativité ne démontre pas à elle seule un type 2 ; une positivité isolée doit aussi être confrontée à la réserve sécrétoire et au tableau clinique [S4, S10].</p>{chain(['Âge et histoire familiale connus','Phénotype et auto-immunité confrontés','Réserve sécrétoire contextualisée','Test spécialisé si décision modifiée'],'Démarche non anatomique de typage, sans règle absolue d’âge ou de marqueur [S4, S5, S10].')}<p>Dans une auto-immunité lente de l’adulte, la sécrétion peut être mieux conservée au diagnostic. La présence d’un syndrome métabolique n’exclut pas cette forme. L’objectif est de prévoir une éventuelle baisse de réserve et d’organiser un suivi ; un anticorps positif n’impose pas dans tous les cas le même schéma au même jour [S4, S10].</p><p>Le repère SSED 2023 de peptide C &gt;200 et &lt;600 pmol/L, anticorps négatifs et absence de forte histoire familiale soutient une insulinodéficience dans le contexte décrit. Il ne constitue pas une norme universelle : le prélèvement, la glycémie, le rein et l’évolution comptent. La SSED rappelle qu’un type 1 précoce reste possible et qu’un contrôle ultérieur peut être nécessaire [S5, S10].</p><p>Les sous-groupes issus d’analyses de cohortes illustrent l’hétérogénéité des diabètes de l’adulte. Ils ne sont pas des critères officiels de E14 ni une preuve de traitement individualisé validé pour chaque patient. Le besoin de traiter une carence insulinique prime sur l’attente d’une classification de recherche [S4, S5].</p>{links('Le tableau familial et l’auto-immunité modifient les probabilités sans décider seuls.','Le test génétique est ciblé ; anticorps et peptide C apportent des informations complémentaires.','Une insulinodéficience menaçante est traitée avant le résultat génétique ou immunologique.','Le type est une conclusion clinique soutenue par des examens, puis réévaluée.')}{src('[S4] tableau 1 et §3 ; [S5] sous-types et déficit ; [S10] valeurs/limites et utilité des marqueurs.')}</section>'''
labels=[('semio','Sémiologie fondamentale et analytique'),('anat','Anatomie'),('histo','Histologie'),('physio','Physiologie'),('bioch','Biochimie'),('gene','Génétique et immunologie')]
sc='<div class="panel" id="pS" hidden><div class="sci-bar ui" role="tablist">'
for i,(code,label) in enumerate(labels):sc+=f'<button id="e14-tab-{code}" role="tab" aria-selected="{str(i==0).lower()}" aria-controls="e14-s-{code}" data-s="e14-s-{code}">{label}</button>'
sc+='</div><div class="chap-body sci-body">'
for i,(code,label) in enumerate(labels):sc+=f'<div class="sci" role="tabpanel" aria-labelledby="e14-tab-{code}" id="e14-s-{code}"'+(' hidden' if i else '')+'>'+units[code]+'</div>'
sc+='</div>'+pager+'</div>'
# Exams are assembled by the following module.
# Sciences fragment is assembled directly into canonical E14_c below.
print('sciences written',list(units))
def quiz(n,q,opts,answer):return '<div class="quiz ui" id="e14-quiz-'+str(n)+'"><p><b>Cas '+str(n)+'.</b> '+q+'</p>'+''.join(f'<button data-ok="{int(ok)}">{txt}</button>' for txt,ok in opts)+'<p class="fb" hidden>'+answer+'</p></div>'
def local_sec(anchor,title,body):return f'<section class="ilot" id="e14-{anchor}"><h2>{title}</h2>{body}</section>'
ex=[]
ex.append(local_sec('e-1','Choisir l’examen selon la question',f'''<p>Il n’existe pas un test unique répondant au diagnostic, à la gravité et au type. Chaque prescription demande une question précise et un résultat capable de modifier la conduite [S4, S10, S11].</p>{table(['Question','Examen pertinent','Interprétation et limite'],[['Diabète confirmé ?','Glycémie plasmatique, HbA1c standardisée ou épreuve orale selon contexte','La confirmation chez l’asymptomatique respecte le test et sa méthode.'],['Crise présente ?','Glucose, électrolytes, créatinine, cétones, gaz veineux ; osmolalité selon tableau','Le β-hydroxybutyrate aide au diagnostic et au suivi ; une bandelette seule est plus limitée.'],['Auto-immunité ?','Autoanticorps ciblés','Un résultat s’interprète dans le tableau clinique, sans devenir un ordre de traitement universel.'],['Sécrétion endogène ?','Peptide C avec glycémie et fonction rénale','Le repas ou la stimulation et la méthode conditionnent le seuil.'],['Complication rénale ?','Filtration estimée et rapport albumine/créatinine','Une chronicité doit être établie ; une cause non diabétique reste possible.'],['Pied ischémique ?','Examen, Doppler et indices de pression selon suspicion','Aucun chiffre isolé ne suffit à exclure la maladie artérielle.']])}<p>Une glycémie très élevée change l’urgence, mais ne classe pas le type. Un peptide C conservé change une probabilité ; il ne dispense pas d’évaluer les cétones [S10, S11].</p>{key('La question clinique détermine le test, les conditions de mesure et la décision attendue.')}'''))
ex.append(local_sec('e-2','Glycémie, hémoglobine glyquée et valeurs intermédiaires',f'''<p>La glycémie mesure une concentration à un instant donné. L’HbA1c reflète une exposition liée à l’hémoglobine, dont la durée de vie et la méthode influencent le résultat. Les repères intermédiaires suivants sont des catégories de risque, et non l’intervalle de référence de tout laboratoire [S14].</p>{table(['Mesure','Sous la zone intermédiaire citée','Zone intermédiaire SSED 2011','Seuil diabète OMS 2019'],[['À jeun, plasma','&lt;5,6 mmol/L','5,6–6,9 mmol/L','≥7,0 mmol/L'],['Deux heures après 75 g','&lt;7,8 mmol/L','≥7,8 à &lt;11,1 mmol/L','≥11,1 mmol/L'],['HbA1c standardisée','&lt;5,7 %','5,7–6,4 %','≥6,5 % (48 mmol/mol)']])}<p>La borne post-charge 11,1 est exclue de la zone intermédiaire pour éviter un chevauchement : elle répond déjà au seuil diabétique OMS. Une valeur sous le seuil d’HbA1c ne réfute pas une hyperglycémie pathologique établie par le plasma. La {w('hba','discordance HbA1c/glycémie')} demande une vérification de la méthode et du renouvellement érythrocytaire [S4, S14].</p>{quiz(1,'Une personne asymptomatique a une HbA1c de 6,6 % isolée. Aucun élément de crise n’est présent. Quelle suite respecte l’OMS ?',[('Le diabète est exclu, car la glycémie manque.',False),('Le résultat doit être confirmé rapidement, de préférence par le même test un autre jour.',True),('Le type 2 est certain et le traitement est déterminé.',False)],'La confirmation ne doit pas être confondue avec le typage. Une méthode fiable et les facteurs d’interférence sont vérifiés ; le résultat isolé ne prouve pas un type [S4, S14].')}{key('Le seuil de diagnostic, la zone de risque et la cible thérapeutique sont trois repères différents.')}'''))
ex.append(local_sec('e-3','Peptide C et anticorps : lire les conditions avant le chiffre',f'''<p>Le peptide C est produit avec l’insuline endogène. En revanche, son élimination et celle de l’insuline diffèrent. L’insuline injectée ne contient pas de peptide C ; le dosage reste utile sous traitement, à condition de connaître le contexte glycémique et rénal [S10].</p>{table(['Situation','Ce qu’elle change','Erreur à éviter'],[['Hypoglycémie au prélèvement','La sécrétion est physiologiquement diminuée.','Le résultat bas ne se lit pas comme une destruction β certaine.'],['Insuffisance rénale','L’élimination du peptide C diminue.','Un résultat conservé ne prouve pas une réserve suffisante.'],['Début du diabète','Une réserve peut persister dans le type 1.','La valeur mesurable ne supprime pas le risque d’insulinodéficience.'],['Valeur stimulée très basse','La revue propose &lt;0,2 nmol/L pour un déficit absolu dans ses populations.','Ce repère n’est pas le seuil à jeun ; méthode et proximité de la borne comptent.'],['Peptide C &gt;200 et &lt;600 pmol/L avec anticorps négatifs','La SSED décrit un contexte d’insulinodéficience, sans exclure un type 1 précoce.','Le résultat ne devient pas un intervalle normal universel.']])}<p>Le repère stimulé &lt;0,2 nmol/L de la revue correspond à &lt;200 pmol/L. Un prélèvement à jeun n’a pas le même seuil proposé. La {w('peptide','fenêtre du peptide C')} précise la conversion, la glycémie simultanée et les limites [S10].</p>{quiz(2,'Un adulte obèse, traité par insuline depuis peu, a un peptide C mesurable avec une insuffisance rénale. Peut-on exclure un type 1 ?',[('Oui, l’obésité et le peptide C suffisent.',False),('Non, la durée, la glycémie, la fonction rénale et l’auto-immunité doivent être confrontées.',True),('Oui, toute insuline injectée apporte du peptide C.',False)],'Le peptide C reflète la sécrétion endogène, mais le rein et la glycémie changent sa lecture. La sécrétion peut persister au début d’un diabète auto-immun [S10].')}{key('Un résultat mesure une fonction dans des conditions connues ; il ne remplace pas le dossier clinique.')}'''))
ex.append(local_sec('e-4','Crise, résolution et dépistage des complications',f'''<p>Dans une crise, les examens suivent une trajectoire. L’équipe ne s’arrête pas à la baisse du glucose si les cétones ou l’acidose persistent. La {w('osmoles','formule d’osmolalité')} et le {w('anion','trou anionique')} ont des usages distincts [S11, S17].</p>{table(['Mesure de suivi','Repère du consensus adulte','Limite'],[['Glycémie','Contrôle toutes les une à deux heures','Une baisse ne signifie pas résolution de l’acidocétose.'],['Potassium','Contrôle deux heures après début d’insuline puis toutes les quatre heures','La substitution dépend aussi du rein, de la diurèse et du produit.'],['Résolution d’acidocétose','Cétones &lt;0,6 mmol/L et pH ≥7,3 ou bicarbonate ≥18 mmol/L','Le trou anionique et la cétonurie ne sont pas les critères privilégiés.'],['Résolution hyperosmolaire proposée','Osmolalité &lt;300, cognition améliorée, diurèse &gt;0,5 ml/kg/h et glycémie &lt;13,9 mmol/L','Il s’agit d’une définition proposée ; l’état clinique est suivi.'],['Bilan chronique','Rapport urinaire albumine/créatinine, filtration, œil et pied','Une anomalie atypique ne doit pas être automatiquement attribuée au diabète.']])}<p>Une catégorie rénale exige une persistance, pas seulement deux résultats proches. Le {w('rein','rapport urinaire et la filtration')} indique les unités et les facteurs qui modifient le suivi [S15].</p>{quiz(3,'Sous un traitement favorisant la cétose, un patient diabétique vomit. Glycémie 9 mmol/L, β-hydroxybutyrate 4,2, pH 7,18 et bicarbonate 9. Quelle hypothèse est prioritaire ?',[('L’acidocétose est exclue par la glycémie.',False),('Une acidocétose euglycémique impose une prise en charge urgente.',True),('Une simple zone de prédiabète suffit à expliquer le tableau.',False)],'Le diabète connu satisfait la première composante malgré le glucose modéré. Cétones et acidose établissent les autres composantes ; la situation est urgente [S11].')}{quiz(4,'Après traitement, le β-hydroxybutyrate est de 0,5 mmol/L, le pH de 7,31 et le bicarbonate de 17. Le critère de résolution de l’acidocétose est-il atteint ?',[('Oui, cétones &lt;0,6 et pH ≥7,3 satisfont le critère.',True),('Non, la cétonurie doit absolument disparaître.',False),('Non, le trou anionique doit toujours être normal.',False)],'Le critère relie cétones basses et pH ou bicarbonate corrigé. La situation globale, la glycémie et le relais doivent encore être appréciés ; la cétonurie peut rester trompeuse [S11].')}{key('La résolution métabolique, la stabilité clinique et la sécurité du relais sont vérifiées ensemble.')}'''))
(R/'chapters/E14/E14_c.html').write_text('<div class="panel" id="pE" hidden><div class="chap-body">'+''.join(ex)+'</div>'+pager+'</div>'+sc)
ph=[]
ph.append(local_sec('p-1','Choisir selon l’urgence et l’insulinodéficience',f'''<p>Le code E14 ne désigne aucun traitement propre. Une crise demande un protocole hospitalier ; une insulinodéficience impose une couverture insulinique ; un type 2 confirmé ouvre une stratégie multifactorielle. L’absence de type précis ne justifie pas un traitement oral automatique [S4, S5, S11].</p>{table(['Situation','Principe','Précaution suisse'],[['Crise hyperglycémique','L’équipe coordonne eau, insuline, glucose et électrolytes.','Les FI des produits exacts et leurs incompatibilités sont vérifiées.'],['Insulinodéficience sans crise','Une insulinothérapie individualisée et une éducation sont organisées.','NovoRapid est une insuline rapide ; hors pompe adaptée, il ne remplace pas à lui seul une couverture basale.'],['Type 2 devenu probable/confirmé','La SSED envisage metformine et protection cardio-rénale selon le patient.','Glucophage est contre-indiqué dans l’acidose ou la déshydratation aiguë ; la filtration limite la dose.'],['Hypoglycémie sévère','L’entourage et les secours assurent le traitement.','Baqsimi 3 mg nasal est autorisé dès un an ; il exige des réserves de glycogène.']])}<p>Les autres classes de type 2 sont évoquées comme stratégie de la SSED, sans ordonnance de produit non vérifié. Un inhibiteur du cotransport sodium-glucose peut favoriser une acidocétose euglycémique ; il est arrêté à l’admission lors d’une acidocétose et sa reprise n’est pas routinière selon le consensus [S5, S11].</p>{key('Le médicament dépend de l’état clinique et du produit, pas du code.') }'''))
ph.append(local_sec('p-2','Monographies suisses exactes : dose et population',f'''<p>Les doses ci-dessous concernent les formulations nommées. Les débits de perfusion de crise proviennent du consensus adulte ; ils ne sont pas présentés comme des doses écrites dans la FI NovoRapid [S11, S23].</p>{table(['Produit et version','Posologie et voie','Adaptations ou limites'],[[w('metformine','Glucophage comprimés, octobre 2025'),'Adulte : début 500–1000 mg/j par voie orale, augmentation de 500 mg tous les cinq à sept jours selon tolérance ; maximum 3000 mg/j.','En filtration 30–59 : début 500 ou 850 mg/j, maximum 1000 mg/j en deux prises. Sous 30 : contre-indiqué.'],[w('novorapid','NovoRapid 100 unités/ml, avril 2026'),'La FI décrit des besoins totaux usuels d’insuline de 0,5–1 unité/kg/j, individualisés ; la fraction rapide dépend du schéma.','Voie sous-cutanée liée au repas ; voie intraveineuse uniquement professionnelle et surveillée. Les débits/kg/h de crise ne sont pas un total/jour.'],[w('baqsimi','Baqsimi poudre nasale, mars 2026'),'3 mg dans une narine, dose unique, dès un an ; aucune inspiration nécessaire.','Pas d’adaptation rénale/hépatique forfaitaire ; aucune étude formelle spécifique. Sous un an : non recommandé.']])}<p>Une dose maximale n’est pas une cible. Chez le sujet âgé ou en insuffisance rénale/hépatique, le besoin d’insuline peut diminuer ; la surveillance et l’adaptation sont individualisées. L’intervalle 30–59 de Glucophage est volontairement plus large que celui de certains tableaux génériques : c’est la FI de ce produit qui est citée [S19, S23].</p><p>Le {w('calculdose','calcul d’unités par kilogramme et par heure')} distingue débit d’insuline, concentration préparée et vitesse de pompe. Une confusion entre unité/ml et unité/kg/h peut être grave [S11, S23].</p>{key('Dose, formulation, voie, fréquence et population restent attachées à la même source.')}'''))
ph.append(local_sec('p-3','Contre-indications, interactions et surveillance',f'''<p>L’acidose et la défaillance rénale aiguë changent immédiatement le rapport bénéfice-risque de la metformine. L’hypoglycémie et l’hypokaliémie sont des risques essentiels de l’insuline. Le glucagon peut être inefficace lorsque les réserves hépatiques de glycogène sont épuisées [S18, S19, S23].</p>{table(['Produit','Risques ou contre-indications','Surveillance et réponse'],[['Glucophage','Acidose, coma/précoma diabétique, filtration &lt;30, insuffisance hépatique, hypoxie aiguë et déshydratation ; interactions rénales, alcool et contraste iodé.','Le produit est arrêté dans la situation aiguë ; fonction rénale et reprise sont réévaluées. Troubles digestifs et vitamine B12 sont surveillés.'],['NovoRapid','Hypoglycémie, hypokaliémie ; erreur de dose, de produit ou de site ; hypersensibilité.','Glycémie et potassium sont suivis en perfusion. Rotation des sites, repas et dispositifs sont vérifiés ; les bêtabloquants peuvent masquer les signes.'],['Baqsimi','Hypersensibilité et phéochromocytome contre-indiqués ; prudence insulinome ; efficacité réduite si jeûne, alcoolisme ou insuffisance surrénale.','Une aide est appelée ; rien n’est donné par bouche à une personne qui ne peut avaler. Des glucides sont pris après récupération. Indométacine et warfarine sont considérées.']])}<p>La FI Glucophage impose, pour un examen intravasculaire iodé si filtration &lt;60, un arrêt 48 heures avant puis une réévaluation rénale 48 heures après. Une chirurgie prévue sous anesthésie générale, spinale ou péridurale suit également un arrêt 48 heures avant et une reprise au plus tôt 48 heures après avec alimentation et fonction rénale satisfaisantes. Ces règles exactes ne sont pas remplacées par une formule générique [S19].</p><p>Des symptômes évoquant une acidose lactique sous metformine imposent l’arrêt et une évaluation hospitalière urgente. La {w('metformine','monographie complète')} précise interactions, grossesse, allaitement et fonction rénale [S19].</p>{key('Une dose correcte peut devenir dangereuse si la situation clinique ou une interaction change.')}'''))
ph.append(local_sec('p-4','Perfusions : distinguer protocole syndromique et produit',f'''<p>Un protocole de crise décrit une stratégie dans une population. Une FI décrit un produit autorisé, ses concentrations, limites et contre-indications. Le passage de l’un à l’autre demande une vérification explicite : une même classe ne garantit pas la même conformité [S11, S23–S24, S26–S31].</p>{table(['Document','Ce qu’il établit','Ce qu’il ne permet pas de déduire'],[['Consensus adulte 2024','Il propose insuline, remplissage et potassium selon le syndrome et les résultats.','Il n’autorise pas automatiquement toute ampoule suisse.'],['NovoRapid 100 unités/ml','La voie intraveineuse professionnelle et certaines concentrations compatibles sont décrites.','La FI ne contient pas le débit de 0,1 unité/kg/h de l’acidocétose.'],['KCl B. Braun et Sintetica','Les concentrés doivent être dilués ; acidose, déshydratation grave et insuffisance rénale figurent parmi les contre-indications.','Le débit de potassium du consensus ne devient pas une ordonnance de ces concentrés en crise.'],['Chlorure de sodium Baxter/Bichsel et Ringer-Acetat Fresenius','Les produits ont leurs indications, volumes, débits et contre-indications propres.','Une déshydratation hypertonique n’est pas une indication automatiquement autorisée de ces produits.']])}<p>La divergence n’est pas effacée et ne justifie pas de retarder sans raison les soins vitaux. Elle impose une décision du médecin expérimenté et une vérification par la pharmacie/protocole hospitalier du produit, de la préparation, de la surveillance et du cadre d’emploi. Aucun produit alternatif non vérifié n’est présenté ici comme solution. La {w('potassium','fenêtre potassium et concentrés')} et la {w('fluides','fenêtre cristalloïdes exacts')} exposent les limites [S11, S24, S26–S31].</p><p>Le bicarbonate n’est pas administré en routine dans le consensus ; une acidose très sévère relève d’une décision experte. Le phosphate n’est pas substitué systématiquement. Aucune dose d’un produit de bicarbonate ou phosphate non relu n’est ajoutée [S11].</p>{key('La stratégie de réanimation et l’autorisation d’un produit sont confrontées avant préparation ; leur divergence reste visible.')}'''))
(R/'chapters/E14/E14_d.html').write_text('<div class="panel" id="pP" hidden><div class="chap-body">'+''.join(ph)+'</div>'+pager+'</div></div></template>')
print('exams/pharma',len(ex),len(ph))
pops=[]
def pop(k,title,body):pops.append(f'<template data-pop="e14-{k}" data-title="{html.escape(title,quote=True)}">{body}</template>')
pop('classification','Classification : une conclusion clinique réévaluable',f'''<div class="lab">Ce qui est classé</div><p>Le diabète est confirmé par des critères de glycémie ou d’HbA1c dans des conditions adaptées. Le type décrit le mécanisme probable : destruction β-cellulaire, résistance associée à dysfonction sécrétoire, forme hybride ou autre cause spécifique. Une information insuffisante justifie un type provisoire, pas l’absence de traitement [S4].</p><div class="lab">Raisonnement</div><p>Le médecin recherche d’abord le besoin d’insuline et les urgences. Il confronte ensuite histoire, âge, phénotype, famille, auto-immunité et sécrétion. Une maladie du pancréas, une endocrinopathie ou un médicament peut changer l’hypothèse. Aucun élément isolé n’est décisif dans tous les cas [S4, S5, S10].</p><div class="lab">Limite</div><p>La catégorie OMS « non classé » est temporaire. Son rapprochement avec E14 n’est pas une correspondance administrative officielle démontrée. L’insuline reçue ne classe pas le type ; les sous-groupes de cohortes ne sont pas des sous-codes de E14 [S1, S4, S20].</p>''')
pop('peptide','Peptide C : sécrétion, concentration et interprétation',f'''<div class="lab">De la molécule au sang</div><p>Le clivage de la proinsuline produit une molécule d’insuline et une de peptide C. Leur sécrétion est équimolaire. Leurs concentrations périphériques ne sont pas égales : une partie importante de l’insuline est extraite par le foie et sa demi-vie est plus courte. La revue décrit environ 20–30 minutes pour le peptide C contre 3–5 pour l’insuline [S10].</p><div class="lab">Ce qui est mesuré</div><p>L’insuline injectée n’apporte pas de peptide C. Le résultat estime donc la sécrétion endogène actuelle. Une insuffisance rénale peut augmenter le taux sanguin ; un prélèvement pendant une hypoglycémie peut le diminuer. Le laboratoire doit connaître jeûne ou repas/stimulation, glycémie simultanée et méthode [S10].</p><div class="lab">Unités et repères</div><p>Un nmol/L représente 1000 pmol/L. Ainsi 0,2 nmol/L correspond à 200 pmol/L. Dans la revue, un peptide C stimulé &lt;0,2 nmol/L soutient un déficit absolu ; le seuil proposé à jeun est différent (&lt;0,08 nmol/L). Ces repères proviennent de populations insulinotraitées et ne sont pas des références universelles ; une valeur proche d’une borne exige prudence [S10, tableau 1].</p><p>La SSED 2023 décrit un contexte de peptide C &gt;200 et &lt;600 pmol/L avec anticorps négatifs et sans forte histoire familiale. Une insulinodéficience est alors envisagée ; un type 1 précoce reste possible. La méthode, le repas, le glucose et le rein empêchent d’appliquer ce nombre sans contexte [S5, S10].</p><div class="lab">Conséquence</div><p>Une réserve conservée au début ne réfute pas un type 1. L’utilité discriminante augmente après plusieurs années ; cela n’interdit pas un dosage plus précoce pertinent. L’insulinothérapie nécessaire n’attend pas le résultat [S10, S5].</p>''')
pop('semio','Sémiologie : plainte, mécanisme et décision','''<div class="lab">Chronologie</div><p>La polyurie décrit une augmentation de volume, tandis qu’une pollakiurie décrit des mictions fréquentes. Le médecin précise nycturie, boissons, perte de poids et durée. Le glucose urinaire entraîne de l’eau et des électrolytes, ce qui relie hyperglycémie, polyurie, soif et déplétion [S4, S11].</p><div class="lab">Gravité</div><p>Vomissements, respiration profonde et troubles cognitifs changent l’urgence. La respiration de Kussmaul compense une acidose ; son absence ne l’exclut pas. La douleur abdominale peut être liée à la crise ou à sa cause et demande une nouvelle évaluation si elle persiste après correction [S11].</p><div class="lab">Examen et interprétation</div><p>La pression artérielle apparemment préservée peut masquer une déplétion dans l’hyperosmolarité. L’examen est confronté aux électrolytes, cétones, pH et osmolalité. La première décision concerne la sécurité ; le type sera précisé ensuite [S11, S17].</p>''')
pop('hba','HbA1c : seuil, cible et interférences',f'''<div class="lab">Diagnostic et cible</div><p>Le seuil de diabète retenu est ≥6,5 % ou 48 mmol/mol avec une méthode standardisée. Chez l’asymptomatique, le résultat est confirmé. La zone 5,7–6,4 % citée par la SSED 2011 exprime un risque intermédiaire ; elle ne signifie pas absence certaine de diabète si le plasma répond à un critère. Une cible de traitement autour de 7 % n’est pas un seuil de normalité [S4, S5, S14].</p><div class="lab">Discordances</div><p>Les hémoglobinopathies et les changements de renouvellement érythrocytaire peuvent modifier la mesure ou sa signification. Hémolyse, transfusion, insuffisance sévère rénale/hépatique et carence martiale demandent une interprétation prudente. La direction et l’importance peuvent dépendre de la méthode et du contexte ; le laboratoire participe à l’analyse [S14].</p><div class="lab">Situations rapides ou particulières</div><p>Le diagnostic aigu d’un type 1 possible ne doit pas attendre l’HbA1c. Le diagnostic de diabète gestationnel utilise un parcours spécifique. L’OMS retient les bornes ≥ ; le document suisse 2011 utilise parfois >. Cette différence historique est déclarée, pas fusionnée [S4, S14].</p>''')
pop('pied','Pied diabétique : la douleur absente ne rassure pas',f'''<div class="lab">Examen</div><p>Le pied est inspecté sur toutes ses faces. Le médecin décrit profondeur et localisation d’une plaie, rougeur, chaleur, tuméfaction, déformations, pouls et sensibilité. Le monofilament et la pallesthésie évaluent des fonctions différentes. Les repères QCARE de monofilament 4/4 et vibration &gt;4/8 appartiennent à son parcours ; ils n’excluent pas toute neuropathie dans toute technique [S12, S13].</p><div class="lab">Limite vasculaire majeure</div><p>La simplification QCARE « deux pouls et indice ≥0,9 » ne permet pas une exclusion universelle d’artériopathie. IWGDF/ESVS/SVS recommande de combiner Doppler, indice cheville-bras et indice orteil-bras. La maladie devient moins probable avec indice cheville-bras 0,9–1,3, indice orteil-bras ≥0,70 et flux bi- ou triphasique ; aucun résultat isolé ne suffit à l’exclure [S25].</p><div class="lab">Urgence</div><p>Ulcère/gangrène avec infection et ischémie demande un avis vasculaire urgent. Dans ce contexte, les repères d’ischémie sévère IWGDF comprennent indice cheville-bras &lt;0,4, pression cheville &lt;50 mmHg, pression orteil &lt;30 mmHg, pression transcutanée d’oxygène &lt;30 mmHg ou Doppler monophasique/absent. Ces valeurs ne doivent pas être mélangées avec les seuils légèrement différents du parcours QCARE [S13, S25].</p><p>Une plaie profonde/plantaire, une évolution défavorable ou un pied chaud évoquant Charcot nécessite une montée de niveau. L’absence de douleur peut refléter la neuropathie et ne diminue pas l’urgence [S13].</p>''')
pop('crise','Crises adultes : stratégie, surveillance et résolution',f'''<div class="lab">Diagnostic</div><p>L’acidocétose exige diabète connu ou glucose ≥11,1 mmol/L, cétones élevées et acidose. La figure 2 du consensus précise β-hydroxybutyrate ≥3 ou cétonurie ≥2+, pH &lt;7,3 et/ou bicarbonate &lt;18. Une glycémie plus basse est possible chez le diabétique connu, notamment sous traitement favorisant la cétose [S11].</p><div class="lab">Traitement hospitalier</div><p>Le consensus adulte coordonne remplissage, insuline, électrolytes et cause. L’insuline rapide en perfusion est généralement débutée à 0,1 unité/kg/h dans l’acidocétose après sécurisation du potassium ; sous 13,9 mmol/L de glucose, l’ajout de glucose et une réduction usuelle à 0,05 permettent de poursuivre la correction des cétones. Les valeurs sont un protocole syndromique, pas une posologie inscrite dans toute FI [S11, S23].</p><p>Dans l’état hyperosmolaire sans acidose (pH ≥7,3, bicarbonate ≥18), le consensus décrit 0,05 unité/kg/h ; en forme mixte, il décrit 0,1. JBDS privilégie d’abord la correction hydrique et peut différer l’insuline tant que le glucose baisse avec elle. Bicarbonate 15–17,9 ou contexte complexe demande une analyse experte plutôt qu’un automatisme [S11, S17].</p><div class="lab">Limites de vitesse</div><p>Pour l’état hyperosmolaire, le consensus évite une baisse glycémique dépassant 5–6,7 mmol/L/h, une baisse de sodium &gt;10 mmol/L/24 h et une baisse d’osmolalité au-delà de 3–8 mOsm/kg/h. La hausse initiale du sodium sous correction du glucose ne suffit pas à décider un soluté hypotonique [S11].</p><div class="lab">Surveillance et sortie de crise</div><p>Le glucose est suivi toutes les une à deux heures ; électrolytes, créatinine, cétones et pH environ toutes les quatre heures. La résolution de l’acidocétose exige cétones &lt;0,6 et pH ≥7,3 ou bicarbonate ≥18. Le trou anionique et la cétonurie ne sont pas des critères privilégiés. Le relais sous-cutané prévoit un recouvrement d’une à deux heures avant arrêt de perfusion, avec dose adaptée au produit et au patient [S11].</p><p>Le protocole est adulte. Grossesse, fragilité, dialyse, atteinte cardiaque et enfance demandent une adaptation ; les limites de produits suisses restent visibles dans les fenêtres dédiées [S11, S17, S23–S24, S26–S31].</p>''')
pop('potassium','Potassium : impératif physiologique et limites de produit',f'''<div class="lab">Pourquoi la kaliémie trompe</div><p>Le déficit total dans l’acidocétose est souvent de 3–6 mmol/kg, mais l’acidose et le manque d’insuline déplacent le potassium vers le sang. Une valeur normale ou élevée n’exclut pas le déficit. L’insuline le fait rentrer dans les cellules et peut provoquer une chute dangereuse [S11, S23].</p><div class="lab">Repères du consensus adulte</div><p>Si la kaliémie est &lt;3,5 mmol/L, le consensus préconise une substitution et retarde l’insuline jusqu’à &gt;3,5. Il décrit un repère de 10 mmol/h dans cette situation et généralement 20–30 mmol de potassium par litre de soluté lorsque nécessaire pour viser 4–5 mmol/L. La diurèse, la fonction rénale et les contrôles conditionnent toute mise en œuvre. Ce repère n’est pas une prescription des concentrés nommés ci-dessous [S11].</p><div class="lab">Produits suisses effectivement lus</div>{table(['Produit','Concentration','Limite décisive'],[['Kaliumchlorid B. Braun 7,45 %/14,9 %, janvier 2007','1 ou 2 mmol/ml','La FI mentionne acidose, déshydratation sévère, insuffisance rénale, anurie/oligurie, hyperkaliémie et hyperchlorémie parmi les contre-indications.'],['Kalium chloratum 15 % Sintetica, février 2024','2 mmol/ml','Les contre-indications comprennent également acidose, déshydratation grave et insuffisance rénale.'],['KCl 7,45 % Sintetica, février 2024','1 mmol/ml','La dilution est obligatoire ; la même divergence avec l’acidocétose demeure.']])}<p>Aucun concentré ne s’administre non dilué. Les FI demandent un contrôle de diurèse, de kaliémie et de l’électrocardiogramme. Leur énumération n’autorise pas une substitution de marque ni un usage automatique pendant une acidose [S24, S26, S29].</p><div class="lab">Décision et limite explicite</div><p>Le besoin vital de traiter l’hypokaliémie est conservé. Le médecin hospitalier expérimenté et la pharmacie confrontent le protocole de crise au produit exact et à son cadre d’emploi. Le cours ne fournit pas une ordonnance d’ampoules qui ignorerait la FI et n’invente pas un produit alternatif. Une insuffisance rénale, une anurie ou une hyperkaliémie excluent toute supplémentation automatique [S11, S24, S26, S29].</p>''')
pop('osmoles','Osmolalité : formule, unités et interprétation',f'''<div class="lab">Base du calcul</div><p>La tonicité décrit l’effet des osmoles efficaces sur les mouvements d’eau. Le sodium et le glucose contribuent au calcul utile ; l’urée contribue à l’osmolalité totale mais n’est pas une osmole efficace de la même manière. Toutes les concentrations de la formule doivent être en mmol/L [S11, figure 2 ; S17].</p><div class="lab">Deux formules distinctes</div>{table(['Calcul','Formule','Exemple fictif'],[['Efficace','2 × sodium + glucose','Sodium 140 et glucose 35 donnent 2 ×140 +35 =315.'],['Totale','2 × sodium + glucose + urée','Avec urée 10 : 280 +35 +10 =325.']])}<p>Ces valeurs calculées approchent l’osmolalité et sont généralement exprimées par convention clinique en mOsm/kg dans les recommandations ; le laboratoire peut calculer autrement ou mesurer directement. Le compte rendu doit préciser formule et unités [S17].</p><div class="lab">Interprétation</div><p>Le consensus 2024 retient efficace &gt;300 ou totale &gt;320 dans les critères de l’état hyperosmolaire, avec glycémie ≥33,3 et les autres critères. L’exemple dépasse les deux repères mais ne donne pas à lui seul le diagnostic : cétones, acidose et clinique sont encore nécessaires [S11].</p><p>Pendant le traitement, la trajectoire est suivie pour éviter une baisse trop rapide. Une natrémie qui monte alors que le glucose baisse n’impose pas à elle seule un soluté hypotonique [S11, S17].</p>''')
pop('anion','Trou anionique : charges mesurées et limites',f'''<div class="lab">Pourquoi ce calcul</div><p>Le plasma reste électriquement équilibré. Le laboratoire mesure certains ions majeurs ; les autres charges ne disparaissent pas parce qu’elles ne figurent pas dans le calcul. Le trou anionique estime la différence entre le sodium mesuré et les principaux anions mesurés [S11].</p><div class="lab">Formule sans potassium</div><p>Trou anionique = sodium − (chlorure + bicarbonate), avec chaque valeur en mmol/L. Exemple pédagogique : sodium 140, chlorure 100 et bicarbonate 14 donnent 140 −114 =26 mmol/L. Le consensus cite &gt;12 comme compatible avec une acidose à anions non mesurés ; le contexte et les références du laboratoire restent nécessaires [S11].</p><div class="lab">Pièges</div><p>Des troubles mixtes peuvent modifier pH et bicarbonate. Après des volumes chlorés importants, une acidose hyperchlorémique peut persister alors que la cétose est corrigée. Le trou anionique n’est donc pas recommandé comme critère privilégié de résolution de l’acidocétose ; on préfère cétones et pH ou bicarbonate. Une autre cause d’acidose peut aussi coexister [S11].</p>''')
pop('rein','Rein : rapport urinaire, filtration et chronicité',f'''<div class="lab">Deux axes complémentaires</div><p>La filtration estimée décrit une fonction ; le rapport albumine/créatinine urinaire décrit une perte d’albumine rapportée à un marqueur de concentration urinaire. Le bilan suisse recommande créatinine ou cystatine C et rapport sur échantillon au moins annuels chez l’adulte diabétique [S15].</p>{table(['Albuminurie','Rapport albumine/créatinine','Sens'],[['A1','&lt;3 mg/mmol','Elle est normale à légèrement augmentée dans cette classification.'],['A2','≥3 à &lt;30 mg/mmol','Elle est modérément augmentée.'],['A3','≥30 mg/mmol','Elle est fortement augmentée.']])}<p>Le rapport ne se calcule pas si les unités sont incompatibles. Exemple pédagogique : albumine urinaire 40 mg/L divisée par créatinine 10 mmol/L donne 4 mg/mmol, catégorie A2. Une valeur isolée ne démontre pas la chronicité. La synthèse suisse demande une persistance d’au moins trois mois de baisse du débit et/ou d’albuminurie pour la maladie chronique [S15].</p><div class="lab">Ne pas tout attribuer au diabète</div><p>Hématurie active, dégradation rapide de filtration, albuminurie rapidement croissante ou syndrome néphrotique demandent une évaluation néphrologique. Une atteinte aiguë influence en outre la metformine, l’insuline et l’interprétation du peptide C ; les mêmes chiffres n’ont pas la même conséquence dans un état stable et une crise [S15, S10, S19, S23].</p>''')
pop('cibles','Cibles de traitement : individualiser sans confondre normalité',f'''<div class="lab">Objectif partagé</div><p>La SSED propose souvent une HbA1c de 7 % pour le type 2. Cette cible est ajustée avec le patient selon durée, complications, hypoglycémies, comorbidités et espérance de vie. Elle ne s’applique pas mécaniquement à une grossesse ni à une crise [S5].</p>{table(['Contexte décrit par SSED 2023','Objectif possible','Condition'],[['La plupart des adultes type 2','Autour de 7 %','Le risque hypoglycémique et les préférences sont considérés.'],['Certains patients plus jeunes/durée courte','Environ 6,5 %','L’objectif doit rester réalisable sans hypoglycémies significatives répétées.'],['Fragilité, hypoglycémies sévères, comorbidités ou espérance de vie limitée','Souvent 7–8 %, parfois objectif symptomatique simplifié','La prévention des hypoglycémies et la charge de traitement priment.']])}<p>Pour une cible d’HbA1c voisine de 7 %, la SSED cite souvent un temps dans l’intervalle 3,9–10 mmol/L d’au moins 70 %. Ce pourcentage est un objectif de suivi sous capteur, pas un critère diagnostique ni une norme biologique de jeûne. Un capteur ne remplace pas les dosages hospitaliers nécessaires pendant une crise [S5, S11].</p>''')
pop('conduite','Conduite automobile : règles suisses 2025 contextualisées',f'''<div class="lab">Population</div><p>Les règles ci-dessous concernent le premier groupe médical et les catégories privées décrites par la directive 2025. Le transport professionnel et les autres catégories demandent leurs conditions propres. Complications visuelles, neurologiques, cardiovasculaires, déséquilibre et perception des hypoglycémies sont évalués [S8].</p>{table(['Risque selon traitement/situation','Mesures principales','Repères'],[['Faible risque selon directive','Le lecteur et les glucides restent dans le véhicule.','Le contrôle avant chaque trajet peut être dispensé dans les conditions décrites.'],['Risque moyen sans surveillance continue','La glycémie est vérifiée avant départ et au moins toutes les deux heures lors d’un long trajet.','Sous 4 mmol/L : pas de conduite ; correction puis attente minimale de 45 minutes. À 4–5 : glucides selon directive.'],['Risque élevé sans surveillance continue','Les contrôles précèdent chaque trajet et sont réguliers pendant les longs trajets.','La cible avant/durant le trajet est ≥5 ; à 4–5, la directive décrit 10–20 g de glucides.'],['Hypoglycémie sévère ou perception altérée','Une évaluation spécialisée est nécessaire.','Les exigences de surveillance renforcée sont définies par la directive.']])}<p>Une surveillance continue avec alarmes change les exigences mais ne dispense pas de corriger une tendance descendante ou une hypoglycémie. Sous 4 mmol/L, le trajet est interrompu ; le délai minimal après correction reste 45 minutes, et une mesure capillaire est recommandée en cas de doute. Le document ne doit pas être réduit à « jamais conduire sous 5 » dans tous les traitements [S8].</p><div class="lab">Portée</div><p>Le médecin confronte les règles à la situation et au permis. Cette fenêtre n’est ni une autorisation de conduire ni une expertise de médecine du trafic [S8].</p>''')
codes=json.loads((R/'nosology/fragments/S05.json').read_text())['lessons'];sub=[x for x in codes if x['code'].startswith('E14.') and len(x['code'])==6]
pop('nosologie','Sous-codes suisses et décompensation documentée',f'''<div class="lab">Après le diagnostic clinique</div><p>E14 indique un type sans précision. Les catégories E10, E11, E12 et E13 décrivent des types ou causes précisés ; la grossesse et le diabète néonatal ont leur classification distincte. L’insuline reçue ne démontre pas une dépendance primaire ni un type 1 [S1, S3, S20].</p>{table(['Sous-code terminal local 2024','Libellé'],[[x['code'],html.escape(x['title'].replace('Diabète sucré, sans précision: ',''))] for x in sub])}<p>Les dix familles E14.0 à E14.9 sont reliées dans le corps du cours à leurs situations cliniques ; les vingt codes terminaux ci-dessus décrivent les subdivisions disponibles du catalogue suisse local. E14.00, E14.10, E14.70 et E14.71 n’y sont pas inventés [S1].</p><div class="lab">Décompensation</div><p>Le manuel suisse 2025 utilise le cinquième caractère et juge le métabolisme sur l’ensemble de la prise en charge, rétrospectivement. La glycémie d’admission seule n’est pas son critère de contrôle. Ses exemples comprennent hypoglycémies symptomatiques répétées &lt;3 mmol/L avec surveillance et adaptation, forte variabilité, HbA1c nettement élevée ou valeurs &gt;15 répétées avec modification thérapeutique. Ces repères de codage ne remplacent pas les critères cliniques d’urgence [S20].</p><p>Le diagnostic principal dépend de la priorité thérapeutique de l’hospitalisation et des manifestations ; les règles DRG détaillées ne sont pas remplacées par un choix de code sur tableau. Le catalogue de cours reste 2024 et le manuel lu 2025 : aucune certification du codage 2026 n’est revendiquée [S1, S20].</p>''')
pop('calculdose','Insuline : calcul d’un débit et limites de la préparation',f'''<div class="lab">Grandeurs différentes</div><p>Le débit thérapeutique en unité/kg/h est multiplié par le poids en kg pour donner unité/h. La concentration préparée en unité/ml permet ensuite de convertir ce débit en ml/h. Le flacon à 100 unités/ml n’est pas d’emblée la concentration de la perfusion [S11, S23].</p><div class="lab">Exemple pédagogique adulte</div><p>Pour 60 kg au repère du consensus 0,1 unité/kg/h : 60 ×0,1 =6 unités/h. Si une préparation professionnelle vérifiée contient 1 unité/ml, la pompe délivre 6 ÷1 =6 ml/h. Avec 0,05 unité/kg/h, le résultat serait 3 unités/h. Ces calculs n’établissent pas l’indication chez le patient ni une recette de dilution [S11].</p><div class="lab">Produit et sécurité</div><p>La FI NovoRapid 100 unités/ml décrit, pour certaines solutions et récipients compatibles, des concentrations 0,05–1 unité/ml stables 24 heures ; elle signale une adsorption initiale sur le matériel. La préparation, le contenant, la voie et le protocole sont vérifiés. Glycémie et potassium sont surveillés ; une hypokaliémie peut retarder l’insuline selon le consensus [S23, S11].</p><p>Le besoin total sous-cutané exprimé par jour est une autre grandeur. Il ne doit pas être remplacé par le débit horaire d’une crise. L’insuffisance rénale/hépatique, l’alimentation et la fragilité changent les besoins [S23].</p>''')
pop('metformine','Glucophage : FI suisse octobre 2025, produit exact',f'''<div class="lab">Indications et mécanisme</div><p>Les comprimés Glucophage 500, 850 et 1000 mg contiennent la metformine. La FI indique le type 2 en complément des mesures de vie, avec possibilités d’associations. Elle décrit aussi un complément dans certains types 1 avec résistance à l’insuline ; ce n’est jamais un remplacement de l’insuline déficitaire. Le produit réduit notamment la production hépatique de glucose et améliore la réponse insulinique [S19].</p><div class="lab">Adultes : voie orale et titration</div><p>Le début est 500–1000 mg/j, augmenté selon glycémie et tolérance de 500 mg tous les cinq à sept jours. La dose usuelle d’entretien est 1500–2000 mg/j et le maximum 3000 mg/j. Les prises sont réparties avec ou après les repas, habituellement deux à trois ; une augmentation progressive réduit les troubles digestifs. La durée est chronique tant que l’indication et la tolérance persistent, avec réévaluation [S19].</p>{table(['Filtration estimée ou clairance','Dose de cette FI','Contrôle rénal'],[['≥60, état stable','Titration usuelle selon patient','Au moins annuel si fonction normale ; davantage si risque.'],['45–59 ml/min/1,73 m²','Début 500 ou 850 mg/j ; maximum 1000 mg/j en deux prises','Tous les trois à six mois.'],['30–44 ml/min/1,73 m²','Même maximum 1000 mg/j, sans autre facteur d’acidose lactique','Au moins tous les trois mois.'],['&lt;30 ml/min/1,73 m²','Contre-indiqué ; arrêt','Une dégradation aiguë demande une action immédiate.']])}<p>La clairance est exprimée en ml/min ; le débit estimé indexé en ml/min/1,73 m². La FI cite les deux : le prescripteur utilise la grandeur appropriée, sans en faire deux mesures identiques chez tous les gabarits. Le plafond 30–59 de ce produit n’est pas remplacé par celui d’un tableau de classe [S19].</p><div class="lab">Contre-indications et situations aiguës</div><p>Hypersensibilité, acidose métabolique, coma/précoma diabétique, fonction rénale sous le seuil, insuffisance hépatique, intoxication alcoolique aiguë/alcoolisme et situations aiguës hypoxiques ou menaçant le rein contre-indiquent le produit. Une déshydratation par vomissements/diarrhée ou une infection grave peut imposer l’arrêt. Une suspicion d’acidose lactique impose arrêt et hospitalisation [S19].</p><div class="lab">Contraste, chirurgie et interactions</div><p>Si filtration ou clairance &lt;60 avant contraste iodé intravasculaire, arrêt 48 heures avant et reprise uniquement si le contrôle rénal 48 heures après n’indique pas d’aggravation. Pour chirurgie prévue sous anesthésie générale, spinale ou péridurale, arrêt 48 heures avant ; reprise au plus tôt 48 heures après avec alimentation orale et fonction rénale satisfaisantes. Alcool, diurétiques, médicaments néphrotoxiques et inhibiteurs du transport rénal peuvent augmenter le risque ; la glycémie et le rein guident l’adaptation [S19].</p><div class="lab">Effets indésirables et populations</div><p>Les troubles digestifs sont fréquents au début ; la carence en vitamine B12 est décrite et une anémie/neuropathie demande de l’évaluer. L’acidose lactique est très rare mais grave. Chez l’enfant dès dix ans, la FI décrit début 500 ou 850 mg et maximum 2000 mg/j en deux à trois prises ; sous dix ans, le produit n’est pas utilisé. Cette indication ne vaut pas traitement d’un type 1 présumé [S19].</p><p>En grossesse, la FI permet d’envisager le produit si indication clinique avec surveillance de la croissance ; elle demande de ne pas débuter ou d’arrêter s’il existe des facteurs de petit poids de naissance. L’allaitement exige de peser bénéfice maternel et risque théorique pour le nourrisson. Une maladie mitochondriale connue/suspectée appelle une prudence spécifique et le produit n’y est pas recommandé [S19].</p><p class="src"><a href="https://amiko.oddb.org/fr/fi?gtin=7680260610169" target="_blank" rel="noopener">[S19] Swissmedic/AIPS via AmiKo, Glucophage, octobre 2025</a>, passages relus le 2 novembre 2026. Aucune substitution par une autre formulation.</p>''')
pop('novorapid','NovoRapid : insuline aspart 100 unités/ml, FI avril 2026',f'''<div class="lab">Produit et mécanisme</div><p>NovoRapid est une insuline aspart rapide à 100 unités/ml, indiquée dans le diabète quand l’insuline est nécessaire. Son action réduit le glucose et déplace le potassium vers les cellules. La FI relue concerne ce produit exact ; la voie et le dispositif sont vérifiés avant usage [S23].</p><div class="lab">Administration et dose</div><p>La dose est individualisée. La FI cite des besoins totaux usuels de 0,5–1 unité/kg/j chez l’adulte et l’enfant dès deux ans, avec fraction rapide généralement 50–70 % dans un schéma basal-bolus et le reste en insuline intermédiaire/prolongée. Ce repère n’est ni un maximum ni une dose de crise. L’injection sous-cutanée est généralement immédiatement avant le repas, parfois juste après selon situation [S23].</p><p>Début d’action sous-cutané environ 10–20 minutes, maximum une à trois heures et durée trois à cinq heures. La rotation des sites limite lipodystrophie/amyloïdose et variations d’absorption. Une pompe compatible peut assurer débit basal et bolus ; un secours est nécessaire en cas de panne. Hors ce contexte, une insuline rapide seule ne couvre pas automatiquement toute la journée [S23].</p><div class="lab">Voie intraveineuse</div><p>La FI l’autorise par un professionnel avec garantie de suivi et contrôle étroit du glucose et du potassium. Elle décrit des solutions et récipients compatibles à 0,05–1 unité/ml pendant 24 heures et une adsorption initiale. Elle ne fournit pas les débits/kg/h du consensus de crise ; ils restent attribués à [S11]. Aucune recette universelle de mélange n’est déduite d’une simple liste de compatibilité [S23].</p><div class="lab">Contre-indications et risques</div><p>L’hypersensibilité est contre-indiquée. Hypoglycémie et hypokaliémie sont des risques majeurs ; une hypoglycémie sévère peut provoquer perte de conscience ou convulsions. Des erreurs de produit/concentration, des repas omis ou des injections dans un tissu remanié peuvent provoquer des fluctuations. Les allergies, réactions locales et œdèmes doivent être considérés [S23].</p><div class="lab">Interactions et adaptations</div><p>Les bêtabloquants peuvent masquer les signes ; l’alcool peut majorer l’hypoglycémie. Corticostéroïdes et autres médicaments peuvent augmenter les besoins ; d’autres traitements les diminuer. Insuffisance rénale/hépatique et âge avancé imposent une adaptation individualisée avec contrôles renforcés, sans réduction forfaitaire unique. Grossesse et allaitement sont possibles avec suivi et adaptation ; les données sous deux ans sont limitées et la surveillance doit être étroite [S23].</p><p class="src"><a href="https://amiko.oddb.org/fr/fi?gtin=7680550450024" target="_blank" rel="noopener">[S23] Swissmedic/AIPS via AmiKo, NovoRapid, avril 2026</a>, relue le 2 novembre 2026.</p>''')
pop('baqsimi','Baqsimi : glucagon nasal 3 mg, FI mars 2026',f'''<div class="lab">Indication et dose</div><p>Baqsimi 3 mg poudre nasale est indiqué pour l’hypoglycémie sévère chez le diabétique dès un an. Une tierce personne administre une dose unique de 3 mg dans une narine ; aucune inspiration profonde n’est nécessaire. Un trouble de conscience ne permet pas d’attendre que le patient s’administre le produit [S18].</p><div class="lab">Mécanisme et conduite</div><p>Le glucagon active les récepteurs hépatiques et la libération de glucose à partir du glycogène. Des réserves suffisantes sont nécessaires. Une aide médicale urgente est sollicitée ; aucune prise orale n’est donnée tant que la déglutition n’est pas sûre. Après récupération, des glucides par bouche contribuent à reconstituer les réserves et prévenir une récidive [S18].</p><div class="lab">Limites et contre-indications</div><p>Hypersensibilité et phéochromocytome sont contre-indiqués. Un insulinome peut provoquer une récidive par libération d’insuline. Jeûne, abus chronique d’alcool, insuffisance surrénale ou hypoglycémie chronique peuvent réduire l’efficacité ; l’équipe peut devoir administrer du glucose. Sous un an, Baqsimi n’est pas recommandé faute de données [S18].</p><div class="lab">Interactions et effets indésirables</div><p>L’indométacine peut diminuer l’effet voire favoriser une hypoglycémie ; l’effet anticoagulant de la warfarine peut augmenter. Les bêtabloquants peuvent majorer transitoirement pouls et pression. Nausées, vomissements, céphalées et irritation nasale/aérienne sont les effets fréquemment rapportés ; une réaction allergique est possible [S18].</p><div class="lab">Populations particulières</div><p>Aucune adaptation forfaitaire liée au rein, au foie ou à l’âge n’est requise ; aucune étude formelle dédiée rénale/hépatique n’a été réalisée. Grossesse et allaitement sont possibles selon la FI. L’absence d’ajustement ne démontre pas une efficacité dans toute déplétion en glycogène [S18].</p><p class="src"><a href="https://amiko.oddb.org/fr/fi?gtin=7680674650010" target="_blank" rel="noopener">[S18] Swissmedic/AIPS via AmiKo, Baqsimi, mars 2026</a>, relue le 2 novembre 2026.</p>''')
pop('fluides','Cristalloïdes suisses : aucune interchangeabilité présumée',f'''<div class="lab">Repère de crise adulte</div><p>Le consensus propose saline isotonique ou cristalloïde équilibré à 500–1000 ml/h pendant deux à quatre heures chez l’adulte sans limitation cardiaque/rénale, puis adaptation. Ce chiffre ne dispense pas de vérifier le produit ; une fragilité ou une insuffisance d’organe demande une stratégie plus prudente [S11].</p>{table(['Produit exact','Données de la FI','Contre-indications importantes'],[['Chlorure de sodium 0,9 % Baxter, février 2022','154 mmol/L de sodium et chlorure ; 500 ml–3 L/24 h pour déplétion isotonique, adaptation aux situations extrêmes.','Hypervolémie, hypernatrémie, hyperchlorémie, déshydratation hypertonique.'],['Natrium chloratum Bichsel 0,9 %, octobre 2025','La routine décrite cite 540 ml/h et limite 2000 ml/j, avec possibilité d’adaptation extrême/choc.','Les mêmes quatre contre-indications sont listées.'],['Ringer-Acetat Fresenius, avril 2026','Na 137, K 4 et chlorure 110 mmol/L ; débit adulte recommandé 5 ml/kg/h, maximum 40 ml/kg/j.','Œdèmes, hyperhydratation, déshydratation hypertonique, insuffisance rénale sévère, alcalose, insuffisance cardiaque décompensée, hyperkaliémie.']])}<p>La fenêtre compare les documents ; elle ne constitue pas une ordonnance de l’un de ces produits pour un état hyperosmolaire. Le prescripteur et la pharmacie vérifient état hydrique, sodium, chlorure, potassium, fonction rénale, compatibilités et cadre d’emploi. Le débit syndromique n’annule pas une limite de produit [S27, S30, S31].</p><div class="lab">Mélanges et surveillance</div><p>Les ajouts et les co-perfusions demandent une compatibilité vérifiée. Le calcium du Ringer-Acetat peut précipiter avec certaines substances. Surcharge, œdèmes, troubles du sodium/chlorure et déséquilibre acido-basique sont recherchés ; les conditions de grossesse, âge et défaillance rénale/cardiaque sont individualisées [S27, S30, S31].</p>''')
# Pareto: summaries contain substantive facts and preserve the source relationship.
pareto=[]
for n,s in enumerate(S,1):
 title=re.sub('<[^>]+>','',s[s.index('</span>')+7:s.index('</h2>')]);summary=re.search(r'<div class="key"><b>À retenir.</b>(.*?)</div>',s,re.S)
 if summary:
  k='pareto-e14-'+str(n);pareto.append(f'<template data-pop="{k}" data-title="Essentiel — {html.escape(title,quote=True)}"><p>{summary[1]}</p><p class="ratio" data-cover="e14-{n}"></p></template>')
  for part in ['a','b']:
   p=R/f'chapters/E14/E14_{part}.html';t=p.read_text();start=t.find('id="e14-'+str(n)+'"')
   if start>=0:
    end=t.index('</section>',start);t=t[:end]+f'<button class="pareto-btn ui" data-k="{k}">Essentiel — {title}</button>'+t[end:];p.write_text(t)
for code in units:
 anchor='e14-s-'+code+'-cours';k='pareto-'+anchor;pareto.append(f'<template data-pop="{k}" data-title="Essentiel scientifique"><p>La science normale est confrontée à la perturbation et au contexte. Le diagnostic du type reste distinct du besoin immédiat d’insuline ; la mesure conserve ses conditions et ses limites [S4, S10, S11].</p><p class="ratio" data-cover="{anchor}"></p></template>')
# Source paragraphs inside popups are public paraphrases only.
(R/'chapters/E14/E14_pop1.html').write_text('\n'.join(pops[:10])+ '\n')
(R/'chapters/E14/E14_pop2.html').write_text('\n'.join(pops[10:]+pareto)+'\n')
